5, 0.1); }.bp-action-bar-root { position: fixed; bottom: 48px; left: 50%; transform: translateX(-50%) translateY(0px); z-index: 2147483647; display: flex; align-items: center; padding: 10px 16px 10px 12px; gap: 14px; background: var(--bp-bg-glass); backdrop-filter: blur(40px) saturate(180%); border: 1px solid var(--bp-border-glass); border-radius: 9999px; box-shadow: var(--bp-shadow-primary); animation: 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal none running bp-slide-up; user-select: none; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); font-family: var(--bp-font-family); pointer-events: auto; cursor: default; }@keyframes bp-slide-up { 
